extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_scene", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var collector := find_by_name(main, "Collector")
	if not check("collector_node", collector != null, "La scena deve contenere il nodo Collector"):
		return

	check("fn_move", has_function(collector, "move_toward_station"), "collector.gd deve definire la funzione move_toward_station(delta: float) -> void")
	check("fn_is_near", has_function(collector, "is_near_station"), "collector.gd deve definire la funzione is_near_station(station_x: float) -> bool")
	check("fn_shield", has_function(collector, "update_shield"), "collector.gd deve definire la funzione update_shield(delta: float) -> void")

	var max_lines: int = longest_function_lines("res://collector.gd")
	check("function_length", max_lines <= 6, "Nessuna funzione in collector.gd deve superare 6 righe di codice")

	var untyped: int = untyped_declarations("res://collector.gd")
	check("static_types", untyped == 0, "Tutte le funzioni e i parametri devono avere il tipo esplicito")

	if has_function(collector, "is_near_station"):
		collector.position.x = 600.0
		var near_true = collector.call("is_near_station", 605.0)
		var near_false = collector.call("is_near_station", 620.0)
		check("is_near_logic", near_true == true and near_false == false, "is_near_station deve restituire true solo se la distanza è inferiore a 10 pixel")

	collector.position.x = 100.0
	var start_x: float = collector.position.x
	await wait_frames(20)
	check("collector_moves", collector.position.x > start_x, "La sonda deve continuare ad avanzare verso la stazione")

